head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50014";
scwin.tmp = "null";
scwin.x_path = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.x_path =scwin.tmp.split(","); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50014' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50014.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getEM
 * @description get EM 처리
 * @returns {void}
 * @hidden N
 */
scwin.getEM = function () {
    const obj = $c.util.getComponent('xpathList');
    let cellObj;
    let data;
    let value = "";
    let htmlContent = "null";
    for (let i = 0; i < obj.rows.length; i++) {
        cellObj = obj.rows[i];
        data = cellObj.cells[1];
        value = data.outerText;
        for (let k = 0; k < scwin.x_path.length; k++) {
            if (scwin.x_path[k].indexOf(value) > 0) {
                const em = cellObj.cells[0].outerText;
                const cd_nm = scwin.Hex4ToStr(scwin.x_path[k].substring(0, scwin.x_path[k].indexOf(":")));
                htmlContent = htmlContent.replace(em, "<font color='red'>" + cd_nm + "</font>");
                $c.util.getComponent('txt_formView').setValue(htmlContent);
                break;
            }
        }
    }
    (!obj ? console.warn('[sdd] 표시 전환 대상 미해결: obj') : (("none") === 'none' ? (obj.hide ? obj.hide() : void 0) : (obj.show ? obj.show() : void 0)));
};

/**
 * @method
 * @name Hex4ToStr
 * @description Hex4 To Str 처리
 * @param {*} encode_data encode_data
 * @returns {void}
 * @hidden N
 */
scwin.Hex4ToStr = function (encode_data) {
    let newData = "";
    let iNo = 0;
    for (let i = 0; i < encode_data.length / 4; i++) {
        const str = encode_data.substr(iNo, 4);
        const iNum = parseInt('0x' + str);
        const strChar = String.fromCharCode(iNum);
        newData += strChar;
        iNo = iNo + 4;
    }
    return newData;
};

/**
 * @method
 * @name showForm
 * @description show Form 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.showForm = function (obj) {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/formprocslist/formprocslist.xml') + dma_pageContext.get("formCd") + "&formVer=" + dma_pageContext.get("formVer") + "" + "&lang=" + obj.getValue();
};

/**
 * @method
 * @name printForm
 * @description print Form 처리
 * @returns {void}
 * @hidden N
 */
scwin.printForm = async function () {
    await $c.win.print();
};

/**
 * @method
 * @name copyXpath
 * @description copy Xpath 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.copyXpath = function (obj) {
    navigator.clipboard.setData("Text", "/xbrli:xbrl" + obj.xpath);
};
